contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try withdrawing and assert relation between balances and contract balance
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // deposit into c from this contract so c.balances(address(this)) increases
        c.deposit{value: depositAmount}();

        // read balances before withdraw
        uint256 beforeCallerBalance = address(c).balance; // total contract balance before
        uint256 beforeRecorded = c.balances(address(this));

        bool reverted;
        // attempt withdraw; catch revert to observe whether it succeeded
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCallerBalance = address(c).balance;
        uint256 afterRecorded = c.balances(address(this));

        // If withdraw succeeded (not reverted), then recorded balance decreased by exactly withdrawAmount
        // and contract's balance decreased by at least withdrawAmount (transfer could fail to reduce if payable reentrancy etc, but here require transfer succeeded so contract balance must drop >= amount)
        assert(reverted || (beforeRecorded >= withdrawAmount && afterRecorded + withdrawAmount == beforeRecorded && beforeCallerBalance >= afterCallerBalance + withdrawAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try withdrawing and assert that if withdraw succeeds then the contract's ETH balance decreased by >= amount.
    // We cannot read c.balances (it's not public), so we assert only about observable contract balance and success flag.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Deposit into c from this contract so the contract holds funds for potential withdraw
        c.deposit{value: depositAmount}();

        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        // attempt withdraw; catch revert to observe whether it succeeded
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBalance = address(c).balance;

        // General rule: if withdraw did not revert, the contract's balance must have decreased by at least withdrawAmount
        // and withdraw could only succeed when beforeContractBalance was >= withdrawAmount (necessary for transfer to be possible)
        assert(reverted || (beforeContractBalance >= withdrawAmount && beforeContractBalance >= afterContractBalance + withdrawAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some funds, then call refund() and observe effects.
    // Parameters:
    //  - depositAmount: amount to deposit into c from this contract
    //  - postRefundWithdrawAttempt: amount to attempt withdrawing after refund (we will use it to check that withdrawing the refunded amount now fails)
    function run(uint256 depositAmount, uint256 postRefundWithdrawAttempt) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Make an initial deposit so this contract has a recorded balance in c.
        c.deposit{value: depositAmount}();

        uint256 beforeContractBalance = address(c).balance;

        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 afterContractBalance = address(c).balance;

        bool withdrawReverted;
        // Try to withdraw postRefundWithdrawAttempt to check whether balance was cleared by refund.
        try c.withdraw(postRefundWithdrawAttempt) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General rule:
        // If refund succeeded, then:
        // 1) contract's balance decreased by at least depositAmount (funds left to caller), i.e. beforeContractBalance >= afterContractBalance + depositAmount
        // 2) any attempt to withdraw up to the previously-deposited amount should revert because refund should have zeroed the caller's recorded balance
        // We express 1 and 2 together guarded by refund succeeded.
        assert(refundReverted || (beforeContractBalance >= afterContractBalance + depositAmount && withdrawReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    //  - fundAmount: amount of wei this test will send to c via deposit
    //  - migrateToAddr: address to pass to migrateTo
    function run(uint256 fundAmount, address payable migrateToAddr) public payable {
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Make an initial deposit so the contract holds some ETH.
        // Use deposit only if fundAmount>0 to avoid triggering assert in deposit when msg.value==0
        if (fundAmount > 0) {
            c.deposit{value: fundAmount}();
        }

        uint256 before = address(c).balance;

        bool migratedReverted;
        try c.migrateTo(migrateToAddr) {
            migratedReverted = false;
        } catch {
            migratedReverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: If migrateTo succeeded then the contract's balance becomes zero afterwards.
        // If migrateTo reverted then the contract balance remains unchanged.
        assert(migratedReverted ? (after == before) : (after == 0));
    }

    receive() external payable {}
}

