contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try a sequence of deposit, withdraw, refund, migrateTo and assert a general rule
    function run(uint256 depositAmount, uint256 withdrawAmount, address payable migrateToAddr) public payable {
        require(address(this).balance >= depositAmount);

        // record observables before interactions
        uint256 beforeCbalance = address(c).balance;
        uint256 beforeSelfBalance = address(this).balance;
        uint256 beforeRecorded = c.balances(address(this));

        // perform a deposit into c
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // try withdraw and record whether it reverted
        bool withdrewReverted;
        uint256 afterCbalance_afterWithdraw;
        uint256 afterRecorded_afterWithdraw;
        bool withdrawAttempted = true;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read observables after withdraw attempt
        afterCbalance_afterWithdraw = address(c).balance;
        afterRecorded_afterWithdraw = c.balances(address(this));

        // General rule asserted:
        // If withdraw reverted, then c's recorded balance for this contract did not decrease.
        // If withdraw succeeded, then recorded balance decreased by at most withdrawAmount and contract balance decreased by at most withdrawAmount,
        // and the difference between recorded balances before/after does not exceed the actual Ether moved out of c.
        // This encodes that withdraw cannot create tokens out of thin air and cannot reduce recorded balance below zero.

        if (withdrewReverted) {
            assert(afterRecorded_afterWithdraw >= beforeRecorded);
        } else {
            // amount that recorded balance decreased (non-negative)
            uint256 recordedDecr = beforeRecorded >= afterRecorded_afterWithdraw ? beforeRecorded - afterRecorded_afterWithdraw : 0;
            // amount that contract Ether decreased (non-negative)
            uint256 cDecr = beforeCbalance >= afterCbalance_afterWithdraw ? beforeCbalance - afterCbalance_afterWithdraw : 0;

            // recorded decrease cannot exceed requested withdraw and cannot exceed actual Ether decreased
            assert(recordedDecr <= withdrawAmount && recordedDecr <= cDecr);

            // also recorded decrease is bounded by the prior recorded balance
            assert(recordedDecr <= beforeRecorded);
        }
    }

    receive() external payable {}
}

