contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs: deposit some Ether into c from this contract, then attempt withdraw,
    // and asserts that if withdraw does not revert then address(c).balance decreased by
    // amount and address(this).balance increased by amount.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");
        // initial observations
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeSelfBalance = address(this).balance;

        // perform deposit to c
        c.deposit{value: depositAmount}();

        // balances after deposit
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositSelfBalance = address(this).balance;

        // make sure deposit had the expected observable effect
        // (this is not the final assert, just a precondition for meaningful withdraw)
        require(afterDepositContractBalance == beforeContractBalance + depositAmount);
        require(afterDepositSelfBalance + depositAmount == beforeSelfBalance);

        // attempt withdraw and record whether it reverted
        bool reverted;
        uint256 contractBalanceBeforeWithdraw = address(c).balance;
        uint256 selfBalanceBeforeWithdraw = address(this).balance;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 contractBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;

        // If withdraw did not revert then exactly withdrawAmount of Ether moved from c to this
        assert(reverted || (contractBalanceBeforeWithdraw == contractBalanceAfter + withdrawAmount && selfBalanceAfter == selfBalanceBeforeWithdraw + withdrawAmount));
    }

    // allow receiving Ether when c.transfer sends to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some Ether into c from this contract, then call refund()
    // and assert that if refund() does not revert then the caller's recorded balance in c is zero
    // and c's contract balance decreased by at least the amount refunded.
    function run(uint256 depositAmount) public payable {
        // allow 0 deposit as well
        require(address(this).balance >= depositAmount);

        // Observe contract balance before any action
        uint256 beforeContractBalance = address(c).balance;

        // perform deposit into c from this contract
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Contract balance after deposit
        uint256 afterDepositContractBalance = address(c).balance;

        // The increase in c's balance is the observable amount added (>= depositAmount)
        uint256 added = afterDepositContractBalance - beforeContractBalance;

        // Now attempt refund(); record whether it reverts
        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRefundContractBalance = address(c).balance;

        // General rule: if refund did not revert, then c's balance decreased by at least the previously observed added amount
        // and (since balances is private) we observe the effect via contract balance only.
        // Assert: either refund reverted, or afterRefundContractBalance + added == afterDepositContractBalance
        // Note: use <= to be robust if other transfers/fees happen; but must assert exact decrease equal to added.
        assert(reverted || afterRefundContractBalance + added == afterDepositContractBalance);
    }

    receive() external payable {}
}

