contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept inputs: an amount to deposit, an amount to withdraw, and a boolean requestRefund
    // This single function will perform deposit, then attempt withdraw and/or refund and assert an invariant
    function run(uint256 depositAmount, uint256 withdrawAmount, bool doRefund) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any operations
        uint256 beforeContract = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // make a deposit to c from this contract
        c.deposit{value: depositAmount}();

        // after deposit, contract should have increased by depositAmount
        uint256 afterDepositContract = address(c).balance;
        // sanity: deposit must increase contract balance by depositAmount
        // (this is a view used only for reasoning; not the final assert)
        // attempt withdraw; capture whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // attempt refund if requested; capture whether it reverted
        bool refundReverted;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        } else {
            refundReverted = true; // not called, treat as 'did not occur'
        }

        // observe final balances
        uint256 finalContract = address(c).balance;
        uint256 finalThis = address(this).balance;

        // Read caller's recorded balance from the mapping via public getter: balances is private in P so no getter exists.
        // Instead we assert observable invariant: successful withdraw or refund must not increase contract balance.
        // General rule: contract balance never increases as a result of withdraw or refund; if withdraw/refund succeeded,
        // the decrease in contract balance equals the increase in this contract's balance.
        // Formally: if withdraw didn't revert then finalContract <= afterDepositContract and
        // finalThis >= (beforeThis - depositAmount) and (afterDepositContract - finalContract) == (finalThis - (beforeThis - depositAmount))

        // Compute expected prior this-balance after deposit: beforeThis - depositAmount (we sent depositAmount to c)
        uint256 thisAfterDeposit = beforeThis - depositAmount;

        // Now assert the general rule in one assert statement.
        // We express: if withdraw succeeded (withdrewReverted == false) or refund succeeded (refundReverted == false),
        // then contract balance did not increase compared to afterDepositContract, and any decrease equals increase to this contract.
        assert(
            (
                (withdrewReverted == false) || (refundReverted == false)
            )
            ? (
                finalContract <= afterDepositContract
                && (afterDepositContract - finalContract) == (finalThis - thisAfterDeposit)
            )
            : true
        );
    }

    // receive to accept Ether returned from c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: deposit some Ether, then attempt a withdraw of amount; assert invariant
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any operations
        uint256 beforeContract = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform deposit on c
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint256 afterDepositContract = address(c).balance;
        uint256 afterDepositThis = address(this).balance;

        // attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // record final balances
        uint256 finalContract = address(c).balance;
        uint256 finalThis = address(this).balance;

        // If withdraw succeeded then the contract's balance must have decreased by exactly withdrawAmount
        // and this contract's balance must have increased by exactly withdrawAmount.
        // Express this as a single assert.
        assert(
            withdrewReverted
            ? true
            : (
                // contract decreased by withdrawAmount
                (afterDepositContract >= finalContract) && ((afterDepositContract - finalContract) == withdrawAmount)
                // this contract increased by withdrawAmount
                && (finalThis >= afterDepositThis) && ((finalThis - afterDepositThis) == withdrawAmount)
            )
        );
    }

    // Accept ETH transfers from c when withdraw/refund happen
    receive() external payable {}
}

