contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot access C.balances (it's not public). Instead, we check refund's observable effects:
    // If refund succeeds then address(c).balance does not increase, and calling withdraw(0) should not revert
    // (withdraw requires amount <= balances[msg.sender]; if refund succeeded balances[this]==0 so withdraw(0) is allowed).
    function run() public payable {
        // record contract balance before
        uint256 beforeContract = address(c).balance;

        // call refund and capture whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        uint256 afterContract = address(c).balance;

        // Now try withdraw(0) to probe whether withdraw would revert for amount 0.
        // If refund succeeded, balances[this] should be 0 and withdraw(0) must succeed (not revert).
        bool withdraw0Reverted;
        try c.withdraw(0) {
            withdraw0Reverted = false;
        } catch {
