        uint256 afterContractBal = address(c).balance;

        // If deposit reverted then nothing observed must have changed; if it succeeded
        // then recorded balance must have increased by at least amount and contract balance
        // must have increased by at least amount.
        assert(
            (reverted && afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            || (!reverted && afterRecorded >= beforeRecorded + amount && afterContractBal >= beforeContractBal + amount)
        );
    }

    receive() external payable {}
}

