        // read before-values observable from c
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeMyRecordedBal = c.balances(address(this));

        // perform the deposit call that changes c's state
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterContractBal = address(c).balance;
        uint256 afterMyRecordedBal = c.balances(address(this));

        // General invariant:
        // If deposit did not revert then contract balance increased by exactly amount,
        // and c.balances(this) increased by at least 0 and by at most amount (i.e., it cannot grow by more than the Ether sent),
        // and the increase in c.balances(this) is <= increase in contract balance (no phantom internal credit).
        assert(
            reverted
            || (
                afterContractBal == beforeContractBal + amount
                && afterMyRecordedBal >= beforeMyRecordedBal
                && afterMyRecordedBal <= beforeMyRecordedBal + amount
                && (afterMyRecordedBal - beforeMyRecordedBal) <= (afterContractBal - beforeContractBal)
            )
        );
    }

    // accept Ether so the test can hold funds to send
    receive() external payable {}
}

