contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: no Ether sent by this call itself.
    // We instead rely on c having been funded by prior deposits from this contract in this transaction sequence
    // but since checker deploys a fresh c and then calls run once, we'll first deposit some Ether from this contract.
    function run(uint256 depositAmount) public payable {
        // ensure this contract has enough Ether to send for deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // perform a deposit into c from this contract (may revert)
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read observable state: contract balance and this contract's recorded balance in c (via public mapping getter)
        uint256 contractBal = address(c).balance;
        uint256 recordedBal = c.balances(address(this));

        // attempt refund and capture whether it reverts
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // after refund attempt, read post-state
        uint256 contractBalAfter = address(c).balance;
        uint256 recordedBalAfter = c.balances(address(this));

        // General rule: If refund did not revert then (1) the contract balance did not increase (it can only stay same or decrease),
        // and (2) the recorded balance for this caller is zero afterwards; if refund reverted then nothing is required.
        assert(refundReverted || (contractBalAfter <= contractBal && recordedBalAfter == 0));
    }

    // accept Ether so this test contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read c.balances (it's not public), so we observe effects via address(c).balance
    // and by attempting a withdraw(0) which should succeed if refund cleared the caller's internal balance.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // First, deposit into c from this contract (may revert)
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 beforeContractBal = address(c).balance;

        // Attempt refund and record whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 afterContractBal = address(c).balance;

        // Attempt withdraw(0) to test whether refund cleared the caller's recorded balance.
        // withdraw(0) should succeed iff the caller's recorded balance is >= 0 (but in this contract's logic
        // withdraw checks require(amount <= balances[msg.sender]) so withdraw(0) will always succeed if the call
        // does not revert for other reasons). We capture whether it reverts.
        bool withdrawZeroReverted;
        try c.withdraw(0) {
            withdrawZeroReverted = false;
        } catch {
            withdrawZeroReverted = true;
        }

        // General rule: If refund did not revert then address(c).balance did not increase (it can only stay same or decrease)
        // and a subsequent withdraw(0) by the same caller must not revert (since refund should have set the caller's recorded balance to 0,
        // and withdraw(0) should be allowed). We don't require anything if refund reverted.
        assert(refundReverted || (afterContractBal <= beforeContractBal && withdrawZeroReverted == false));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: amount to deposit and amount to withdraw (both provided by caller); this function may send Ether for deposit
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this test contract has enough balance to fund the deposit
        require(address(this).balance >= depositAmount, "insufficient native balance for deposit");

        // perform deposit (may revert). Record whether deposit reverted.
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // record contract balance before attempting withdraw
        uint256 beforeBal = address(c).balance;

        // attempt withdraw(withdrawAmount) and record whether it reverted
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // record contract balance after withdraw attempt
        uint256 afterBal = address(c).balance;

        // attempt a withdraw(0) afterwards to check whether it reverts
        bool withdrawZeroReverted;
        try c.withdraw(0) {
            withdrawZeroReverted = false;
        } catch {
            withdrawZeroReverted = true;
        }

        // General invariant asserted for all inputs:
        // If withdraw(withdrawAmount) succeeded then the contract's balance decreased by exactly withdrawAmount
        // and a subsequent withdraw(0) by the same caller must not revert.
        // If withdraw reverted we make no claim.
        assert(withdrawReverted || (beforeBal == afterBal + withdrawAmount && withdrawZeroReverted == false));
    }

    receive() external payable {}
}
